import random
class Solution:
    def sortArray(self, a: list[int]) -> list[int]:
        def qsort(lo, hi):
            while lo < hi:
                p = random.randint(lo, hi)
                a[p], a[hi] = a[hi], a[p]
                pivot, i = a[hi], lo
                for j in range(lo, hi):
                    if a[j] < pivot:
                        a[i], a[j] = a[j], a[i]; i += 1
                a[i], a[hi] = a[hi], a[i]
                if i - lo < hi - i:
                    qsort(lo, i - 1); lo = i + 1
                else:
                    qsort(i + 1, hi); hi = i - 1
        qsort(0, len(a) - 1)
        return a

class Solution {
public:
    int findKthLargest(vector<int>& a, int k) {
        int target = a.size() - k, lo = 0, hi = a.size() - 1;
        while (true) {
            int p = lo + rand() % (hi - lo + 1);
            swap(a[p], a[hi]);
            int pivot = a[hi], i = lo;
            for (int j = lo; j < hi; j++) if (a[j] < pivot) swap(a[i++], a[j]);
            swap(a[i], a[hi]);
            if (i == target) return a[i];
            if (i < target) lo = i + 1; else hi = i - 1;
        }
    }
